    22→data class PeerDevice(
    23→    val deviceName: String,
    24→    val deviceAddress: String,
    25→    val isGroupOwner: Boolean = false,
    26→    val ipAddress: String? = null,
    27→    val isConnected: Boolean = false,
    28→)
    29→
    30→sealed class WiFiDirectEvent {
    31→    object WiFiP2pEnabled : WiFiDirectEvent()
    32→    object WiFiP2pDisabled : WiFiDirectEvent()
    33→    data class PeersChanged(val peers: List<WifiP2pDevice>) : WiFiDirectEvent()
    34→    data class ConnectionChanged(val info: WifiP2pInfo?) : WiFiDirectEvent()
    35→    data class DeviceChanged(val device: WifiP2pDevice?) : WiFiDirectEvent()
    36→    data class GroupInfoChanged(val clients: List<PeerDevice>, val isGroupOwner: Boolean) : WiFiDirectEvent()
    37→    data class Error(val message: String) : WiFiDirectEvent()
    38→}
